                fureaiPokeModels[i].collisionModel.ExCollisionUpdate(deltaTime, fureaiPokeModels);

            if (isUpdateStop)
                return;

            GameManager.fieldCamera.SetTempNormalCamera(pitch, fov, far);

            if (isSyuugouPoke || !isInHiroba)
                return;

