            else if ((GameController.on & GameController.ButtonMask.StickRDown) != 0)
            {
                pitch = Mathf.Clamp(deltaTime * 30.0f + pitch, MinPitch, MaxPitch);
            }
            else if ((GameController.on & GameController.ButtonMask.StickRUp) != 0)
            {
                pitch = Mathf.Clamp(pitch - deltaTime * 30.0f, MinPitch, MaxPitch);
            }
            else if ((GameController.on & GameController.ButtonMask.StickRLeft) != 0)
            {
                fov = Mathf.Clamp(deltaTime * 10.0f + fov, MinFov, MaxFov);
            }
            else if ((GameController.on & GameController.ButtonMask.StickRRight) != 0)
            {
                fov = Mathf.Clamp(fov - deltaTime * 10.0f, MinFov, MaxFov);
            }

            if (Input.GetMouseButtonDown(0))
            {
