                    var pos = hits[i].point;
                    var poke = pokeWalkMng.GetPokeWalkers().FindMin(x => Vector3.Distance(pos, x.walkData.entity.transform.position));
                    if (Vector3.Distance(pos, poke.walkData.entity.transform.position) < 1.0f && !poke.controller.emoticon.IsVisible)
                    {
                        poke.AI.GetNowState().Play(new LookAtPosition(Vector3.forward, 6.0f, 1.0f), () =>
