                            if (AnimID == -1)
                                AnimID = FieldPokemonEntity.Animation.Happy03;

                            poke.AI.GetNowState().Play(new PlayAnim(AnimID, 0.2f, 0.0f), null);

                            if (Utils.IsPikaV(poke.monsNo))
                                Utils.PlayVoicePikaBui_Touch(poke.monsNo, poke.controller.voicePlayer);
                            else
                                Utils.PlayVoice(poke.monsNo, poke.GetPokeParam().GetFormNo(), 0, poke.controller.voicePlayer);
                        });
                        poke.controller.emoticon.Enter(3);
                    }
