		public void HirobaEnterKaisan() {
            isKaisanPoke = true;

            var list = pokeFactory.PokeList.FindAll(x => x.nowState == typeof(WaitState));
            pokeFactory.CreatePositionNoList(list.Count);
            var randomList = list.OrderBy(i => Guid.NewGuid()).ToList();

            Sequencer.Start(RouteCheck(randomList));
        }
		public void HirobaExitSyuugou() {
            isSyuugouPoke = true;
            isInHiroba = false;

            ToCameraDefault(1.0f).OnComplete(() => { });

            bool isPlayerLeftEntrance = EntityManager.activeFieldPlayer.worldPosition.x > -45.0f;
            int count = 0;

            pokeFactory.PokeList.ForEach(x =>
            {
                if (Vector3.Distance(x.walkData.entity.transform.position, EntityManager.activeFieldPlayer.worldPosition) > 20.0f)
                {
                    count++;
                    if (isPlayerLeftEntrance)
                        x.Warp(new Vector3(-10 - count * 2, 0.0f, 34.0f), true);
                    else
                        x.Warp(new Vector3(count * -1.5f - 43.5f, 0.0f, 35.0f), true);
                }

                DOVirtual.DelayedCall(0.2f, () =>
                {
                    ((FureaiExitState)x.AI.ChangeState(typeof(FureaiExitState))).OnPlayerNear = () =>
                    {
                        Sequencer.Start(DoEndofFrame(() =>
                        {
                            AudioManager.Instance.PlaySe(AK.EVENTS.PLAY_BA_SYS_BALL_OPEN_FIELD, null);
                            x.CreateWarpEffect();
                            DelPoke(x);

                            if (pokeFactory.PokeList.Count == 0)
                                isSyuugouPoke = false;
                        }));
                    };
                });
            });
        }
		private global::System.Collections.IEnumerator DoEndofFrame(global::System.Action act) {
            yield return new WaitForEndOfFrame();
            act();
        }
		private global::System.Collections.IEnumerator RouteCheck(global::System.Collections.Generic.List<global::Dpr.FureaiHiroba.FureaiPokeModel> list) {
            for (int i = 0; i < list.Count; i++)
            {
                pokeFactory.SetPokePosition(false, null, list[i], default(Vector2Int));
                pokeFactory.SetPairModel(list[i]);
                list[i].CreateRoute(list[i].sanpoModel.InitPos, 60);

                yield return new WaitForEndOfFrame();

                list[i].AI.ChangeState(typeof(GotoSanpoState));
                list[i].AI.GetNowState().Play(new LookAtNextRoute(UnityEngine.Random.Range(2.5f, 3.0f), UnityEngine.Random.Range(0.8f, 1.0f)), null);
            }

            yield return new MyWaitForSeconds(2.0f);

            isKaisanPoke = false;
            isEntering = false;
            AddFirstPoke();
        }
