		public void SelectPokeGotoPlayerNear() {
            FureaiPokeModel selectPoke = pokeFactory.PokeList.Find(x => x.isSelectPoke);
            selectPoke.AI.GetNowState().Cancel();
            selectPoke.AI.ChangeState(typeof(WaitState));
            AICommon.WarpImmidiate(selectPoke.AI.aiModel, true);

            var player = EntityManager.activeFieldPlayer;
            var diff = selectPoke.walkData.entity.transform.position - player.worldPosition;
            player.SetYawAngleDirect(Utils.Vector2ToAngle(new Vector2(diff.x, diff.z), 0.0f));

            int Rank = Utils.GetNakayoshiRank(selectPoke.nakayoshi);
            int motionID = Utils.GetNakayoshiRankMotion(Rank);

            selectPoke.AI.GetNowState().Play(new LookAtPlayer(0.5f, 5.0f), () =>
            {
                selectPoke.AI.GetNowState().PlayAnim(motionID, () => pokeWalkMng.AddPoke(selectPoke));

                if (Utils.IsPikaV(selectPoke.monsNo))
                    Utils.PlayVoicePikaBui_NakayoshiRank(selectPoke.monsNo, Rank, selectPoke.controller.voicePlayer);
                else
                    Utils.PlayVoice(selectPoke.monsNo, selectPoke.GetPokeParam().GetFormNo(), 0, selectPoke.controller.voicePlayer);
            });
        }
		public void TalkStart(int temoti) {
            var poke = pokeFactory.PokeList.Find(x => x.GetPokeParam() == PlayerWork.playerParty.GetMemberPointer((uint)temoti));
            if (poke.isWarping)
                return;

            poke.isForceAnimation = true;
            Sequencer.Start(WaitEventEnd(poke));
        }
		private global::System.Collections.IEnumerator WaitEventEnd(global::Dpr.FureaiHiroba.FureaiPokeModel poke) {
            while (poke.entity.EventParams.IsEventRunning)
                yield return null;

            poke.isForceAnimation = false;
            poke.controller.emoticon.Delete();
        }
		public void PlayVoice_TemotiID(uint temoti) {
            var poke = pokeFactory.PokeList.Find(x => x.GetPokeParam() == PlayerWork.playerParty.GetMemberPointer(temoti));
            var monsNo = poke.monsNo;
            int rank = Utils.GetNakayoshiRank(poke.GetPokeParam().GetFriendship());

            if (Utils.IsPikaV(monsNo))
                Utils.PlayVoicePikaBui_NakayoshiRank(monsNo, rank, poke.controller.voicePlayer);
            else
                Utils.PlayVoice(poke.monsNo, poke.GetPokeParam().GetFormNo(), 0, poke.controller.voicePlayer);
        }
