		public void DebugAddPoke(bool CreatePlayerPosition = false) {
            uint memberCount = PlayerWork.playerParty.GetMemberCount();
            int pokeNum = pokeFactory.PokeList.Count;
            if (pokeNum > 5 || AddPokeCor != null)
                return;

            var pokePara = pokeNum < memberCount ? PlayerWork.playerParty.GetMemberPointer((uint)pokeNum) : null;
            AddPokeCor = pokeFactory.AddPoke(pokePara, model =>
            {
                model.controller.OnPlayerNear += pokeWalkMng.AddPoke;
                model.OnWarp = pokeWalkMng.OnWarp;
                AddPokeCor = null;
            }, CreatePlayerPosition);

            Sequencer.Start(AddPokeCor);
        }
